<template><section><div class="paper-card page-intro"><div><p class="eyebrow">RECOMMEND</p><h1>猜你喜欢</h1><p>根据借阅历史推荐；没有历史时展示全站热门。也可以盲选一本当前可借图书。</p></div><el-button class="primary-action" @click="blind">今日盲选一本书</el-button></div><div v-if="pick" class="paper-card page-section"><h2>今日盲选：{{pick.title}}</h2><p>{{pick.author}} · {{pick.tags}} · 可借 {{pick.stock_available}}</p></div><div class="book-grid"><article v-for="book in rows" :key="book.id" class="book-card"><div class="book-cover"><span>{{book.title?.slice(0,8)}}</span></div><div class="book-info"><el-tag class="category-tag">{{book.category_name}}</el-tag><h3>{{book.title}}</h3><p>{{book.author}}</p><div class="stock-line"><strong>可借 {{book.stock_available}}</strong><span>借阅 {{book.borrow_count}}</span></div></div></article></div></section></template>
<script setup>import{onMounted,ref}from'vue';import{api}from'../api/library';const rows=ref([]),pick=ref(null);async function load(){rows.value=(await api.recommendation()).data||[]}async function blind(){pick.value=(await api.blindPick()).data}onMounted(load)</script>
